import{_ as a,o as e,c as o,a2 as d}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"MiniTavern에서 설정","description":"MiniTavern ↔ Ollama, LM Studio, KoboldCPP, llama.cpp — 설정 → 모델 연결, OpenAI 호환 Base URL과 테스트.","frontmatter":{"title":"MiniTavern에서 설정","description":"MiniTavern ↔ Ollama, LM Studio, KoboldCPP, llama.cpp — 설정 → 모델 연결, OpenAI 호환 Base URL과 테스트.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"MiniTavern에서 설정 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern ↔ Ollama, LM Studio, KoboldCPP, llama.cpp — 설정 → 모델 연결, OpenAI 호환 Base URL과 테스트."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/connect-app/minitavern"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/connect-app/minitavern"}]]},"headers":[],"relativePath":"ko/connect-app/minitavern.md","filePath":"ko/connect-app/minitavern.md","lastUpdated":1787224147000}'),r={name:"ko/connect-app/minitavern.md"};function l(i,t,n,c,s,p){return e(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="minitavern에서-설정" tabindex="-1">MiniTavern에서 설정 <a class="header-anchor" href="#minitavern에서-설정" aria-label="Permalink to &quot;MiniTavern에서 설정&quot;">​</a></h1><p>App 경로: <strong>설정 → 모델 → 모델 연결</strong>.</p><h2 id="연결-새로-만들기" tabindex="-1">연결 새로 만들기 <a class="header-anchor" href="#연결-새로-만들기" aria-label="Permalink to &quot;연결 새로 만들기&quot;">​</a></h2><ol><li>MiniTavern → 하단 <strong>설정</strong>.</li><li><strong>모델</strong> → <strong>모델 연결</strong>.</li><li>오른쪽 위 <strong>새로 만들기</strong>.</li><li><strong>모델 플랫폼</strong>에서 <strong>Custom</strong>（OpenAI 호환 / Custom Base URL, 현재 버전 옵션명）.</li><li>아래 표대로 채우고 저장; <strong>테스트</strong> 지원 시 먼저 테스트 후 기본값.</li></ol><h2 id="도구별-예" tabindex="-1">도구별 예 <a class="header-anchor" href="#도구별-예" aria-label="Permalink to &quot;도구별 예&quot;">​</a></h2><p><code>YOUR_PC_IP</code>를 PC LAN IP로（<code>localhost</code> 금지）.</p><table tabindex="0"><thead><tr><th>도구</th><th>Base URL 예</th><th>모델명</th><th>API Key</th></tr></thead><tbody><tr><td><a href="/ultra_guides/ko/ollama/lan">Ollama</a></td><td><code>http://YOUR_PC_IP:11434/v1</code></td><td><code>ollama list</code> 이름</td><td>비움 또는 <code>ollama</code></td></tr><tr><td><a href="/ultra_guides/ko/lmstudio/server">LM Studio</a></td><td><code>http://YOUR_PC_IP:1234/v1</code></td><td>Local Server id</td><td>비움</td></tr><tr><td><a href="/ultra_guides/ko/koboldcpp/server">KoboldCPP</a></td><td><code>http://YOUR_PC_IP:5001/v1</code></td><td><code>/v1/models</code> id</td><td>비움</td></tr><tr><td><a href="/ultra_guides/ko/llamacpp/server">llama.cpp</a></td><td><code>http://YOUR_PC_IP:8080/v1</code></td><td>server 반환 id</td><td>비움</td></tr><tr><td><a href="/ultra_guides/ko/localai/install">LocalAI</a></td><td><code>http://YOUR_PC_IP:8080/v1</code></td><td>LocalAI 설정명</td><td>인증 여부</td></tr><tr><td><a href="/ultra_guides/ko/jan/install">Jan</a></td><td>앱 API 페이지 주소</td><td>목록 id</td><td>앱 설정</td></tr><tr><td><a href="/ultra_guides/ko/textgen/install">text-generation-webui</a></td><td><code>http://YOUR_PC_IP:포트/v1</code></td><td>확장 반환 id</td><td>확장 설정</td></tr></tbody></table><p>별칭은 자유, 예 <code>집 Ollama</code>, <code>서재 Kobold</code>.</p><h2 id="기본값과-채팅" tabindex="-1">기본값과 채팅 <a class="header-anchor" href="#기본값과-채팅" aria-label="Permalink to &quot;기본값과 채팅&quot;">​</a></h2><ol><li>모델 연결 목록에서 <strong>기본값</strong>.</li><li>캐릭터 가져오기·선택 후 메시지 전송.</li><li>PC 도구에 요청 활동; App에 스트리밍 또는 전체 응답.</li></ol><h2 id="세션-덮어쓰기-선택" tabindex="-1">세션 덮어쓰기（선택） <a class="header-anchor" href="#세션-덮어쓰기-선택" aria-label="Permalink to &quot;세션 덮어쓰기（선택）&quot;">​</a></h2><p>한 채팅만 임시로 로컬 모델: 채팅 설정에서 전역 기본 연결 / 파라미터 덮어쓰기.</p><h2 id="주의" tabindex="-1">주의 <a class="header-anchor" href="#주의" aria-label="Permalink to &quot;주의&quot;">​</a></h2><ul><li>폰에 <code>http://localhost:...</code> 또는 <code>http://127.0.0.1:...</code> <strong>금지</strong>.</li><li>URL 끝은 <code>/v1</code> 권장, <code>/chat/completions</code>까지 쓰지 말 것.</li><li>PC 절전·덮개·네트워크 전환 후 IP 변경 가능.</li><li>포트는 실제 연 값; 위는 흔한 기본.</li></ul><p>연결 안 되면 <a href="/ultra_guides/ko/troubleshoot">문제 해결</a>. 도구: <a href="/ultra_guides/ko/local/tools">도구 개요</a>.</p>',15)])])}const m=a(r,[["render",l]]);export{u as __pageData,m as default};
